Lang["Q2_5722"] = "Fouiller le Gouffre de Ragefeu pour trouver le cadavre de Maur Grimtotem et tout élément intéressant."
Lang["Q2_5723"] = "Chercher le gouffre de Ragefeu dans Orgrimmar, puis tuer 8 Troggs Ragefeu et 8 Chamans Ragefeu avant de revenir auprès de Rahauro à Thunder Bluff."
Lang["Q2_5724"] = "Apporter la Sacoche du Totem sinistre à Rahauro à Thunder Bluff."
Lang["Q2_5725"] = "Apporter les livres de Sorts des Ombres et d’Incantations du Néant à Varimathras, à Undercity."
Lang["Q2_5726"] = "Apporter un Insigne de lieutenant à Thrall à Orgrimmar."
Lang["Q2_5727"] = "Apporter l'Insigne du Lieutenant à Neeru Fireblade et lui parler. Essayer de déterminer s'il vous croit membre de la Lame ardente puis retourner voir Thrall à Orgrimmar."
Lang["Q2_5728"] = "Tuer Bazzalan et Jergosh l'Invocateur avant de retourner voir Thrall à Orgrimmar."
Lang["Q2_5729"] = "Parler à Neeru Fireblade à Orgrimmar."
Lang["Q2_5730"] = "Parler à Thrall à Orgrimmar et lui dire ce que vous avez appris."
Lang["Q2_5742"] = "Écouter ce que Tirion Fordring a à dire."
Lang["Q2_5761"] = "Pénétrer dans le Gouffre de Ragefeu et tuer Taragaman l'Affameur, puis rapporter son coeur à Neeru Fireblade à Orgrimmar."
Lang["Q2_5781"] = "Aller au caveau de Zaeldarr - situé dans la section la plus au sud des Maleterres de l’Est - et récupérer le Marteau de Taelan. Retourner auprès de Tirion Fordring après avoir accompli la mission."
Lang["Q2_5845"] = "Se rendre à Valnord, dans la région nord-est des Maleterres de l’Est, et récupérer le Symbole de l’honneur perdu. Revenir auprès de Tirion Fordring quand la tâche est accomplie."
Lang["Q2_5846"] = "Voyager jusqu’à l’île de Caer Darrow, dans la région centre-sud des Maleterres, et chercher un indice de l’emplacement du tableau."
Lang["Q2_5848"] = "Se rendre à Stratholme, dans la partie nord des Maleterres. C’est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles."
Lang["Q2_5921"] = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_5922"] = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_5923"] = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."
Lang["Q2_5924"] = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."
Lang["Q2_5925"] = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."
Lang["Q2_5926"] = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff."
Lang["Q2_5927"] = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff."
Lang["Q2_5928"] = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff."
Lang["Q2_5929"] = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade."
Lang["Q2_5930"] = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade."
Lang["Q2_5931"] = "Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave."
Lang["Q2_5932"] = "Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise."
Lang["Q2_5961"] = "Parler à Nathanos le Flétrisseur, dans les Maleterres de l’Est. Il se trouve actuellement à la ferme des Marris."
Lang["Q2_6001"] = "Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Mathrengyl Bearwalker in Darnassus when you are done."
Lang["Q2_6002"] = "Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Turak Runetotem in Thunder Bluff when you are done."
Lang["Q2_6022"] = "Allez à l'est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez 7 morceaux de Pourriture vivante en moins de 10 minutes. Utilisez le Mortier et le Pilon pour réduire la Pourriture vivante en Pourriture coagulée."
Lang["Q2_6042"] = "Tuer 20 Chauves-souris pestiférées nuisibles et 10 Chauves-souris pestiférées monstrueuses. Retourner voir Nathanos le Flétrisseur quand ce sera fait."
Lang["Q2_6061"] = "Use the Taming Rod to tame an Adult Plainstrider. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6062"] = "Use the Taming Rod to tame a Dire Mottled Boar. Practice your skills, then return the Taming Rod to Thotar in Razor Hill."
Lang["Q2_6063"] = "Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."
Lang["Q2_6064"] = "Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos."
Lang["Q2_6065"] = "Speak with Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6066"] = "Speak with Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6067"] = "Speak with Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6068"] = "Speak with Thotar at Razor Hill."
Lang["Q2_6069"] = "Speak with Thotar at Razor Hill."
Lang["Q2_6070"] = "Speak with Thotar at Razor Hill."
Lang["Q2_6071"] = "Speak with Dazalar in Dolanaar."
Lang["Q2_6072"] = "Speak with Dazalar in Dolanaar."
Lang["Q2_6073"] = "Speak with Dazalar in Dolanaar."
Lang["Q2_6074"] = "Speak with Grif Wildheart in Kharanos."
Lang["Q2_6075"] = "Speak with Grif Wildheart in Kharanos."
Lang["Q2_6076"] = "Speak with Grif Wildheart in Kharanos."
Lang["Q2_6081"] = "Speak with Ormak Grimshot in Orgrimmar."
Lang["Q2_6082"] = "Use the Taming Rod to tame an Armored Scorpid. Practice your skills, then return to Thotar at Razor Hill."
Lang["Q2_6083"] = "Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill."
Lang["Q2_6084"] = "Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos."
Lang["Q2_6085"] = "Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos."
Lang["Q2_6086"] = "Speak with Belia Thundergranite in Ironforge."
Lang["Q2_6087"] = "Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6088"] = "Use the Taming Rod to tame a Swoop. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."
Lang["Q2_6089"] = "Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff."
Lang["Q2_6101"] = "Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."
Lang["Q2_6102"] = "Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."
Lang["Q2_6103"] = "Speak to Jocaste in the Cenarion Enclave, in Darnassus."
Lang["Q2_6121"] = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_6122"] = "Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.\n\nDeliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore."
Lang["Q2_6123"] = "Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve."
Lang["Q2_6124"] = "Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them.  Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins."
Lang["Q2_6125"] = "Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."
Lang["Q2_6126"] = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."
Lang["Q2_6127"] = "Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.\n\nDeliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens."
Lang["Q2_6128"] = "Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve."
Lang["Q2_6129"] = "Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them.  Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads."
Lang["Q2_6130"] = "Return to Turak Runetotem on the Elder Rise, Thunder Bluff."
Lang["Q2_6133"] = "Aller vers la frontière nord des Maleterres de l’est et récupérer le Registre de Quel'Thalas. L’objet se trouve quelque part dans le gîte de Quel'Lithien. Tuer également 8 Forestiers, 8 Eclaireurs et 8 Bûcherons."
Lang["Q2_6135"] = "Trouver Crépuscaile et la tuer. Récupérer une Touffe de fourrure de Crépuscaile sur son cadavre, puis l’apporter à Nathanos le Flétrisseur.Il paraît que Crépuscaile hante les terres qui se trouvent au nord de la ferme des Marris."
Lang["Q2_6136"] = "Trouver Creusechair, dans les terres au nord des Maleterres de l’est, et le tuer. Retourner voir Nathanos le Flétrisseur quand la mission sera terminée."
Lang["Q2_6141"] = "Adressez-vous au frère Anton, en Désolace."
Lang["Q2_6144"] = "Aller à Undercity et parler à Varimathras."
Lang["Q2_6163"] = "Aller à Stratholme et tuer Ramstein Grandgosier. Prendre sa tête, et l’apporter à Nathanos."
Lang["Q2_63"] = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest."
Lang["Q2_65"] = "Gryan Stoutmantle veut que vous parliez à Wiley à Lakeshire."
Lang["Q2_6521"] = "Apporter la Tête de l'Ambassadeur Malcin à Varimathras, à Undercity."
Lang["Q2_6522"] = "Apporter le Petit parchemin à Varimathras, à Undercity."
Lang["Q2_65593"] = "Apportez les Cœurs d’Avelina Lilly et d’Isaac Pearson à Carendin Halgar dans le Temple des Damnés."
Lang["Q2_65597"] = "Utilisez les Cœurs des amoureux pour invoquer et soumettre un incube, puis rapportez les Cœurs des amoureux à Carendin Halgar, dans le Quartier de la magie d’Undercity."
Lang["Q2_65601"] = "Parlez à Magar, à Orgrimmar."
Lang["Q2_65602"] = "Récupérez la Figurine en bois et rapportez-la à Gakin le Tisse-noir, au Quartier des mages de Stormwind."
Lang["Q2_65603"] = "Using the Wooden Figurine, summon and subdue an incubus, then return the Wooden Figurine to Gakin the Darkbinder in the Slaughtered Lamb."
Lang["Q2_65604"] = "Using the Withered Scarf, summon and subdue an incubus, then return the Withered Scarf to Gan'rul Bloodeye in Orgrimmar."
Lang["Q2_6561"] = "Apporter la tête du Seigneur du crépuscule Kelris à Bashana Runetotem, à Thunder Bluff."
Lang["Q2_65610"] = "Explorez le Lac Tombeciel en Ashenvale et rendez compte de vos découvertes à Gan’rul Bloodeye, à Orgrimmar."
Lang["Q2_6562"] = "Parler à Je'neu Sancrea, à Ashenvale."
Lang["Q2_6563"] = "Apporter 20 Saphirs d'Aku'Mai à Je'neu Sancrea, à Ashenvale."
Lang["Q2_6564"] = "Apporter la Note humide à Je'neu Sancrea, à Ashenvale."
Lang["Q2_6565"] = "Tuer Lorgus Jett, dans les Profondeurs de Brassenoire et retourner voir Je'neu Sancrea, à Ashenvale."
Lang["Q2_6626"] = "Tuer 8 Gardes de guerre Tranchebauge, 8 Tisseurs d'épines Tranchebauge et 8 Sectateur de la Tête de mort, puis retourner voir Myriam Moonsinger, à l’entrée des Souilles de Tranchebauge."
Lang["Q2_6627"] = "Réussir à répondre à la question de Braug Dimspirit, puis lui reparler. Il se trouve dans les Serres-Rocheuses."
Lang["Q2_6628"] = "Réussir à répondre à la question de Parqual Fintallas, puis lui reparler. Il se trouve à Undercity."
Lang["Q2_6681"] = "Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\n\nYour cunning will be tested along the way. Be prepared."
Lang["Q2_6701"] = "Syndicate Emblems"
Lang["Q2_6921"] = "Apporter le Noyau de la brasse à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale."
Lang["Q2_6922"] = "Apporter le Globe d'eau étrange à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale."
Lang["Q2_6981"] = "Allez à Ratchet pour trouver quelqu'un qui puisse vous en dire plus sur l'Eclat luminescent."
Lang["Q2_7028"] = "Collecter 25 Ciselures de Cristaux Théradriques pour Saule, en Désolace."
Lang["Q2_7029"] = "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange, dans Maraudon."
Lang["Q2_7041"] = "Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange dans Maraudon."
Lang["Q2_7044"] = "Retrouver les deux parties du Sceptre de Celebras : le Bâtonnet de Celebras et le Diamant de Celebras."
Lang["Q2_7046"] = "Aidez Celebras le Racheté pendant qu'il recrée le Sceptre de Celebras."
Lang["Q2_7064"] = "Anéantir la princesse Theradras et retourner voir Selendra près de Proie-de-l'Ombre, en Désolace."
Lang["Q2_7065"] = "Tuer la princesse Theradras, et retourner voir le Gardien Marandis, à la Combe de Nijel en Désolace."
Lang["Q2_7066"] = "Chercher Remulos à Reflet-de-Lune, et lui donner la Graine de vie."
Lang["Q2_7067"] = "Lire les instructions du paria. Après cela, obtenir l'Amulette d'union de Maraudon et la ramener au centaure renégat, dans le sud de Désolace."
Lang["Q2_7068"] = "Collecter 10 Fragments d'Ombréclats dans Maraudon, et les ramener à Uthel'nay, à Orgrimmar."
Lang["Q2_7070"] = "Collecter 10 Fragments d'Ombréclats, et les porter à l'archimage Tervosh, dans le marécage d'Âprefange."
Lang["Q2_709"] = "Rapporter la Tablette de Ryun'eh à Theldurin l'Egaré."
Lang["Q2_720"] = "Trouver le Prospecteur Ryedol et lui apprendre que Hammertoe Grez est en vie."
Lang["Q2_7201"] = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals."
Lang["Q2_721"] = "Trouver Hammertoe Grez à Uldaman."
Lang["Q2_722"] = "Trouver l'Amulette de Hammertoe et lui rapporter à Uldaman."
Lang["Q2_7441"] = "Rendez-vous à Hache-tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d’Incantations d’Azj’Tordin."
Lang["Q2_7461"] = "Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d’Immol’thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol’thar se dissipera."
Lang["Q2_7462"] = "Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !"
Lang["Q2_7481"] = "Fouillez Hache-tripes à la recherche de Kariel Winthalus. Lorsque vous aurez des informations, donnez-les au Sage Korolusk de Camp Mojache."
Lang["Q2_7482"] = "Fouillez Hache-tripes à la recherche de Kariel Winthalus. Lorsque vous aurez des informations, donnez-les à l’Erudite Runethorn, à Feathermoon."
Lang["Q2_7488"] = "Ramenez le Filet de Lethtendris à Latronicus Moonspear au bastion de Feathermoon en Feralas."
Lang["Q2_7489"] = "Ramenez le Filet de Lethtendris à Talo Thornhoof au Camp Mojache, en Feralas."
Lang["Q2_7492"] = "Parlez à Talo Thornhoof au Camp Mojache en Feralas."
Lang["Q2_7494"] = "Parlez à Latronicus Moonspear au bastion de Feathermoon en Feralas."
Lang["Q2_7499"] = "Return the book to its rightful owners."
Lang["Q2_7506"] = "Return the book to its rightful owners."
Lang["Q2_7562"] = "Parler à Mor'zul Bloodbringer dans les Steppes ardentes."
Lang["Q2_7563"] = "Apporter 30 bouteilles de Sang de bêtes enragées à Mor'zul Bloodbringer dans les Steppes ardentes."
Lang["Q2_7564"] = "Apporter la Caisse de sang à Gorzeeki Wildeyes dans les Steppes ardentes."
Lang["Q2_7581"] = "Rendez-vous à Hache-tripes en Feralas et récupérez 15 doses de Sang de satyre sur les satyres Follengeance qui habitent le quartier de Crochebois. Lorsque ce sera fait, retournez voir Levandre à la Balafre impure."
Lang["Q2_7582"] = "Rendez-vous à la gorge du Sombre murmure, dans le Berceau-de-l'Hiver, et récupérez 5 Larmes de l’Hederine sur les démons Hederine qui occupent la gorge. Lorsque ce sera fait, retournez voir Levandre à la Balafre impure."
Lang["Q2_7583"] = "Pénétrez dans la Balafre impure et localisez un Commandant de la garde funeste.\n\nServez-vous de la Prison de cristal luminescente sur lui. Attendez-vous à être sauvagement <attaqué/attaquée>, car le démon fera l’impossible pour éviter d’être capturé.\n\nSi vous réussissez, amenez le garde funeste emprisonné à Levadre à la Balafre impure."
Lang["Q2_7601"] = "Parlez à Démonet à Gangrebois."
Lang["Q2_7602"] = "Démonet vous a demandé de lui apporter trois Gangressences parfaites, venant de trois régions distinctes.\n\nLes satyres Legashi d'Azshara, les légionnaires de Jaedenar et les gangregardes sentinelles des Terres foudroyées détiennent la Gangressence parfaite de leur région.\n\nRécupérez les Gangressences parfaites et rapportez-les à Démonet, à Gangrebois."
Lang["Q2_7603"] = "Fouillez le Val Grêlé pour trouver les restes de Kroshius. Quand vous les aurez localisés, utilisez le Gangrefeu à proximité et attendez le retour de Kroshius. Quand l'Infernal se sera réveillé, tuez-le et prenez le Noyau infernal sur son cadavre.\n\nRapportez le Noyau infernal de Kroshius à Niby le Tout-Puissant, à Gangrebois."
Lang["Q2_7621"] = "A Warning"
Lang["Q2_7622"] = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\n\nYou may view the Death Post to view how many Peasants have been slain."
Lang["Q2_7623"] = "Achetez des Potions des ténèbres à Gorzeeki dans les Steppes ardentes.\n\nServez-vous en pour vous rendre à Jaedenar, et parlez au seigneur Banehollow."
Lang["Q2_7624"] = "Affrontez Ulathek, puis apportez le Coeur du traître au seigneur Banehollow à Jaedenar."
Lang["Q2_7625"] = "Acheter de la Poussière d’étoiles xorothienne à Ur’dan. L’apporter à Gorzeeki dans les Steppes ardentes."
Lang["Q2_7626"] = "Apportez 10 Elixirs de Puissance de l'ombre à Gorzeeki Wildeyes dans les Steppes ardentes."
Lang["Q2_7627"] = "Apportez 6 Grands éclats brilliants et 25 charges de Minerai de sombre fer à Gorzeeki dans les Steppes ardentes."
Lang["Q2_7628"] = "Apportez 35 Ecailles de dragon noir à Gozeeki WIldeyes dans les Steppes ardentes."
Lang["Q2_7629"] = "Apporter le Diablotin en bouteille au laboratoire d'alchimie de la Scholomance. Une fois le parchemin créé, retournez voir Gorzeeki Wildeyes."
Lang["Q2_7630"] = "Apporter 3 Barres d’arcanite à Gorzeeki dans les Steppes ardentes."
Lang["Q2_7631"] = "Lisez les Instructions de Mor’zul. Invoquez un Destrier de l’effroi xorothien, vainquez-le, et liez son esprit."
Lang["Q2_7632"] = "Find the owner of the Ancient Petrified Leaf. Good luck, you; It's a big world."
Lang["Q2_7633"] = "An Introduction"
Lang["Q2_7634"] = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood."
Lang["Q2_7635"] = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood."
Lang["Q2_7636"] = "You must find and destroy these four demonic corrupters:\n\nSimone the Seductress.\n\nKlinfran the Crazed.\n\nSolenor the Slayer.\n\nArtorius the Doombringer.\n\nDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\n\nRefer to the Petrified Bark in your inventory for clues as to their whereabouts.\n\nYou MUST complete this task by yourself."
Lang["Q2_7637"] = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer.  You will need to make a donation of 150 gold in order to secure it."
Lang["Q2_7638"] = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."
Lang["Q2_7639"] = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7640"] = "Use the Exorcism Censer to drive out the spirits that torment Terrordale.  When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7641"] = "Speak with Grimand Elmore in Stormwind's Dwarven District."
Lang["Q2_7642"] = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind."
Lang["Q2_7643"] = "Acquire special horse feed used for feeding a spirit horse.  Merideth Carlson in Southshore apparently is the source for such food.\n\nTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood.  Doing so will free the Ancient Equine Spirit.  Feed it the special horse feed, thereby soothing the spirit.  Finally, give it the Arcanite Barding so it may bless it."
Lang["Q2_7644"] = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7645"] = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills.  The Argent Dawn is known as the sole purveyor of the biscuits.\n\nYou also need to give her 50 gold to soothe her ruffled sensibilities."
Lang["Q2_7646"] = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."
Lang["Q2_7647"] = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth the spirits you must judge.  Defeating these spirits will summon forth Death Knight Darkreaver.  Defeat him and reclaim the lost soul of the fallen charger.\n\nGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger."
Lang["Q2_7648"] = "Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection."
Lang["Q2_7666"] = "Again Into the Great Ossuary"
Lang["Q2_7667"] = "If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond."
Lang["Q2_7668"] = "The Darkreaver Menace"
Lang["Q2_7669"] = "Again Into the Great Ossuary"
Lang["Q2_7670"] = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."
Lang["Q2_78916"] = "Apportez la Perle de Brassenoire au gardien de l'aube Selgorm, à Darnassus."
Lang["Q2_78917"] = "Apportez la Perle de Brassenoire à Bashana Totem-runique, aux Pitons-du-Tonnerre."
Lang["Q2_79007"] = "Rendez-vous au 46, 73 dans les Tarides. Interagissez avec les Restes calcinés et acceptez la quête.\n\nRendez-la au 37, 50 dans la Marche de l'Ouest en interagissant avec la Planche clouée. Acceptez Tort-tue depuis cette planche avant de partir."
Lang["Q2_79008"] = "Rendez-vous au 37, 50 dans la Marche de l'Ouest. Interagissez avec les Restes calcinés à côté de la Planche clouée et acceptez la quête.\n\nRendez-la au 46, 73 dans les Tarides, aux Restes calcinés, puis interagissez avec la Planche clouée sur place et acceptez Tort-tue."
Lang["Q2_79192"] = "La Horde l'accepte depuis la Planche clouée au 37, 50 dans la Marche de l'Ouest. L'Alliance l'accepte depuis la Planche clouée au 46, 73 dans les Tarides.\n\nRendez-vous au 51, 51 dans les Serres-Rocheuses. Depuis la route, suivez l'ouverture dans les montagnes et le sentier jusqu'au camp. Interagissez avec les Détritus de poche (40.8, 52.5)."
Lang["Q2_79974"] = "Interagissez avec le Monticule de terre dans les Serres-Rocheuses (39.6, 49.9) pour accepter cette quête.\n\nRendez-vous au barrage au 49, 12 dans le Loch Modan. Sautez jusqu'à la corniche et interagissez avec la Figurine sculptée (49.5, 12.8)."
Lang["Q2_79975"] = "Interagissez avec la Figurine sculptée au barrage du Loch Modan (49.5, 12.8) pour accepter cette quête.\n\nRendez-vous au 81, 56 dans les Contreforts de Hautebrande. Face à la porte vers les Hautes-terres d'Arathi, tournez à gauche et longez le mur jusqu'au chariot renversé. Suivez le parcours de sauts vers le camp, puis interagissez avec la Sacoche de messager (Hautes-terres d'Arathi 22.4, 24.2)."
Lang["Q2_79976"] = "Interagissez avec la Sacoche de messager, puis avec la Sacoche roulée à la hâte juste en dessous pour recevoir le Sac de couchage douillet."
Lang["Q2_79980"] = "Au camp des Serres-Rocheuses, interagissez avec les Détritus de poche (40.8, 52.5) pour accepter cette quête.\n\nTraversez le camp et sautez dans la montagne jusqu'à la corniche du Monticule de terre (39.6, 49.9), puis interagissez avec."
Lang["Q2_79987"] = "Vous pouvez garder l'anneau, ou retrouver la personne responsable de l'empreinte et des gravures à l'intérieur."
